  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Absolute oral bioavailability of the GSK1322322 1500 mg tablet was 77% in healthy volunteers after a meal, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Linezolid demonstrated 100% absolute oral bioavailability at an oral dose of 375 mg in patients, directly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Encainide absolute oral bioavailability was 32 ± 7% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Paliperidone extended-release absolute oral bioavailability was 28% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Rifapentine absolute oral bioavailability was 70% after a single 600 mg dose in healthy adult volunteers, directly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All five highly transferable experimental analogues (transfer likelihood ≥ 0.982) have direct human absolute oral bioavailability values ≥ 20% (28–100%), strongly supporting a high F prediction; the uncertain physicochemical prior is outweighed by this consistent experimental evidence.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the query molecule.",
    "Exact structural similarity between the query and the analogues is not provided; transfer scores are used as applicability weights.",
    "Formulation, food effects, and transporter or metabolic influences on the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

